class User {
public:
    int* data;
    User() { data = new int(10); }
    ~User() { delete data; }
    // implicit copy: data = other.data
};

int main() {
    User a;
    User b = a;
}   // ~b, then ~a

class User {
public:
    int* data;
    User() : data(new int(10)) {}
    User(const User& o) : data(new int(*o.data)) {}  // own int
    User& operator=(const User& o) {
        *data = *o.data;     // copy the value, keep our int
        return *this;
    }
    ~User() { delete data; }
};

